(()=>{const key=document.body.dataset.category,c=DF_CATEGORIES[key];if(!c)return;document.title=`${c.title} | Dongfeng E-Trucks`;document.querySelector('[data-title]').textContent=c.title;document.querySelector('[data-kicker]').textContent=c.kicker;document.querySelector('[data-intro]').textContent=c.intro;document.querySelector('[data-hero]').src=c.hero;const labels=['Model / Application','Drive','GVW / GCW','CATL Battery','Motor rated / peak','Gearbox','Wheelbase','Front / rear axle','Tyres','Safety','Charging / notes'];document.querySelector('[data-models]').innerHTML=c.models.map((m,i)=>`<article class="spec-card"><div class="spec-no">${String(i+1).padStart(2,'0')}</div><div><p class="eyebrow">${m[1]} · ${m[2]}</p><h2>${m[0]}</h2></div><dl>${m.slice(3).map((v,j)=>`<div><dt>${labels[j+3]}</dt><dd>${v}</dd></div>`).join('')}</dl><a class="button outline" href="contact.html?model=${encodeURIComponent(m[0])}">Request this configuration</a></article>`).join('');})();
